import { defineStore } from 'pinia';

export const useUserStore = defineStore('user', {
  state: () => ({
    username: '',
    isLoggedIn: false,
  }),
  actions: {
    setUser(username) {
      this.username = username;
      this.isLoggedIn = true;
    },
    clearUser() {
      this.username = '';
      this.isLoggedIn = false;
    },
  },
});


export const PhoneIdStore = defineStore('defaultPhone', {
  state: () => ({
    phoneIds: ["Alyssa H", "Ashton H", "Alvin H", "Alvin S"],
    defaultPhoneId: localStorage.getItem('defaultPhoneId') || ''
  }),
  actions: {
    setDefaultPhoneId(phoneId) {
      this.defaultPhoneId = phoneId;
      localStorage.setItem('defaultPhoneId', phoneId); // Persist to local storage
    }
  }
});

export const AssigneeIdStore = defineStore('defaultAssignee', {
  state: () => ({
    assigneeIds: ["Alyssa", "Ashton", "Alvin", "All"],
    defaultAssigneeId: localStorage.getItem('defaultAssigneeId') || ''
  }),
  actions: {
    setDefaultAssigneeId(assigneeId) {
      this.defaultAssigneeId = assigneeId;
      localStorage.setItem('defaultAssigneeId', assigneeId); // Persist to local storage
    }
  }
});

export const useCounterStore = defineStore('counter', {
  state: () => ({
    count: 0,
  }),
  getters: {
    counter: (state) => state.count,
  },
  actions: {
    increment() {
      this.count++;
    },
    decrement() {
      this.count--;
    },
  },
});