<template>
  <div v-if="isSaveDialogVisible" class="dialog-wrapper">
    <div class="dialog-content">
      <h2>Card Details</h2>
      <button class="close-button" @click="closeDialog">X</button>

      <card-info :card="selectedCard" />

      <!-- Actions Section -->
      <section class="section-header">
        <h3>Actions</h3>
        <button @click="addAction" class="nice-button">Add Action</button>
      </section>
      <table style="width: 100%; border-collapse: collapse;">
        <thead>
          <tr>
            <th style="border: 1px solid #ccc; padding: 8px; width: 80%;">Task</th>
            <th style="border: 1px solid #ccc; padding: 8px; width: 15%;">Date</th>
            <th style="border: 1px solid #ccc; padding: 8px; width: 15%;">Status</th>
            <th style="border: 1px solid #ccc; padding: 8px; width: 5%;">Actions</th>
          </tr>
        </thead>
        <tbody>
          <action-item v-for="(action, index) in selectedCard.action" :key="index" :action="action" :index="index"
            @remove="removeAction" />
        </tbody>
      </table>

      <!-- Documents Section -->
      <section class="section-header">
        <h3>Documents</h3>
        <button @click="addDocument" class="nice-button">Add Document</button>
      </section>
      <table style="width: 100%; border-collapse: collapse;">
        <thead>
          <tr>
            <th style="border: 1px solid #ccc; padding: 8px; width: 80%;">Description</th>
            <th style="border: 1px solid #ccc; padding: 8px; width: 15%;">URL</th>
            <th style="border: 1px solid #ccc; padding: 8px; width: 5%;"></th>
          </tr>
        </thead>
        <tbody>
          <document-item
            v-for="(document, index) in selectedCard.document"
            :key="index"
            :item="document"
            :index="index"
            @remove="removeDocument"
            @update-url="updateDocumentUrl"
          />
        </tbody>
      </table>

      <!-- Thumbnails Section -->
      <div v-if="selectedCard.document && selectedCard.document.length > 0" class="thumbnails-container">
        <h4>Document Thumbnails</h4>
        <div class="thumbnails">
          <div v-for="(doc, index) in selectedCard.document" :key="index" class="thumbnail-wrapper">
            <div v-if="doc.url">
              <img v-if="isImage(doc.url)" :src="doc.url" alt="Image Thumbnail" class="thumbnail" />
              <img v-else-if="pdfThumbnails[index]" :src="pdfThumbnails[index]" alt="PDF Thumbnail" class="thumbnail" @click="expandPdf(index)" />
              <span v-else>Loading thumbnail...</span>
            </div>
          </div>
        </div>
        <!-- Full PDF Viewer -->
        <div v-if="showPdfIndex !== null" class="pdf-viewer">
          <iframe :src="selectedCard.document[showPdfIndex].url" width="100%" height="300px"></iframe>
          <button @click="closePdf" class="close-pdf-btn">Close PDF</button>
        </div>
      </div>

      <!-- Advertisements Section -->
      <section class="section-header">
        <h3>Advertisements</h3>
        <button @click="addAdvertisement" class="nice-button">Add Advertisement</button>
      </section>
      <table style="width: 100%; border-collapse: collapse;">
        <thead>
          <tr>
            <th style="border: 1px solid #ccc; padding: 8px; width: 80%;">Advertiser</th>
            <th style="border: 1px solid #ccc; padding: 8px; width: 15%;">URL</th>
            <th style="border: 1px solid #ccc; padding: 8px; width: 15%;">Date</th>
            <th style="border: 1px solid #ccc; padding: 8px; width: 5%;"></th>
          </tr>
        </thead>
        <tbody>
          <advertisement-item v-for="(advertisement, index) in selectedCard.advertisement" :key="index"
            :item="advertisement" :index="index" @remove="removeAdvertisement" />
        </tbody>
      </table>

      <rental-info v-if="taskMode === 'lease' || taskMode === 'rent'" :card="selectedCard" />

      <!-- Lease Information -->
      <section class="section-header">
        <h3>Lease Information</h3>
      </section>
      <div class="lease-fields">
        <label for="leaseFrom">Lease From:</label>
        <input type="date" id="leaseFrom" v-model="selectedCard.leaseFrom" />
        <label for="leaseTo">Lease To:</label>
        <input type="date" id="leaseTo" v-model="selectedCard.leaseTo" />
      </div>

      <price-evaluation v-if="taskMode === 'seller'" :card="selectedCard" />

      <div class="action-buttons">
        <button @click="handleSave" class="e-btn e-primary">💾 Save</button>
        <button @click="handleDelete" class="e-btn e-primary">X Delete</button>
        <button @click="closeDialog" class="e-btn">Close</button>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, watch } from 'vue'
import CardInfo from './CardInfo.vue'
import ActionItem from './ActionItem.vue'
import DocumentItem from './DocumentItem.vue'
import AdvertisementItem from './AdvertisementItem.vue'
import RentalInfo from './RentalInfo.vue'
import PriceEvaluation from './PriceEvaluation.vue'
import { updateContact, deleteContact } from "../utils/vgraphql"
import { getDocument } from 'pdfjs-dist/webpack'

export default {
  name: 'CardDetailsDialog',
  components: {
    CardInfo,
    ActionItem,
    DocumentItem,
    AdvertisementItem,
    RentalInfo,
    PriceEvaluation,
  },
  props: {
    isSaveDialogVisible: Boolean,
    selectedCard: Object,
    taskMode: String,
  },
  emits: ['close-dialog', 'save-changes'],

  setup(props, { emit }) {
    console.log('Initial Selected Card:', props.selectedCard)
    const isDeleting = ref(false)
    const pdfThumbnails = ref([])
    const showPdfIndex = ref(null)

    const closeDialog = () => {
      emit('close-dialog')
    }

    const handleSave = async () => {
      try {
        const updatedData = { ...props.selectedCard }
        await new Promise((resolve) => {
          if (confirm('Are you sure you want to save these changes?')) {
            resolve()
          }
        })
        let id = updatedData.id
        await updateContact(updatedData)
        updatedData.id = id
        emit('save-changes', updatedData)
        console.log('Saving changes:', updatedData)
        closeDialog()
      } catch (error) {
        console.error('Error saving card:', error)
        alert('Error saving changes: ' + error.message)
      }
    }

    const handleDelete = async () => {
      isDeleting.value = true
      try {
        await deleteContact(props.selectedCard.id)
        emit('close-dialog')
      } catch (error) {
        console.error('Error deleting contact:', error)
      } finally {
        isDeleting.value = false
      }
    }

    const addAction = () => {
      if (!props.selectedCard.action) props.selectedCard.action = []
      props.selectedCard.action.push({ task: "", date: "", status: "" })
    }

    const addDocument = () => {
      if (!props.selectedCard.document) props.selectedCard.document = []
      props.selectedCard.document.push({ description: "", url: "" })
      pdfThumbnails.value.push('') // Ensure array length matches
    }

    const addAdvertisement = () => {
      if (!props.selectedCard.advertisement) props.selectedCard.advertisement = []
      props.selectedCard.advertisement.push({ advertiser: "", url: "", date: "" })
    }

    const removeAction = (index) => {
      if (props.selectedCard.action && props.selectedCard.action.length > index) {
        props.selectedCard.action.splice(index, 1)
      }
    }

    const removeDocument = (index) => {
      if (props.selectedCard.document && props.selectedCard.document.length > index) {
        props.selectedCard.document.splice(index, 1)
        pdfThumbnails.value.splice(index, 1)
      }
    }

    const removeAdvertisement = (index) => {
      if (props.selectedCard.advertisement && props.selectedCard.advertisement.length > index) {
        props.selectedCard.advertisement.splice(index, 1)
      }
    }

    const updateDocumentUrl = (index, url) => {
      if (props.selectedCard.document && props.selectedCard.document.length > index) {
        props.selectedCard.document[index].url = url
        console.log(`Updated URL at index ${index}: ${url}`)
        if (!isImage(url) && url.endsWith('.pdf')) {
          generatePdfThumbnail(url, index)
        }
      }
    }

    const isImage = (url) => {
      if (!url) return false
      const extension = url.split('.').pop().toLowerCase()
      return ['jpg', 'jpeg', 'png', 'gif'].includes(extension)
    }

    const generatePdfThumbnail = async (pdfUrl, index) => {
      console.log(`Generating thumbnail for PDF at index ${index}: ${pdfUrl}`)
      try {
        const loadingTask = getDocument(pdfUrl)
        const pdf = await loadingTask.promise
        const page = await pdf.getPage(1)
        const viewport = page.getViewport({ scale: 0.2 })
        const canvas = document.createElement("canvas")
        const context = canvas.getContext("2d")

        canvas.height = viewport.height
        canvas.width = viewport.width

        await page.render({
          canvasContext: context,
          viewport: viewport,
        }).promise

        pdfThumbnails.value[index] = canvas.toDataURL()
        console.log(`Thumbnail generated for index ${index}: ${pdfThumbnails.value[index].substring(0, 50)}...`)
      } catch (error) {
        console.error('Error generating PDF thumbnail:', error)
        pdfThumbnails.value[index] = ''
      }
    }

    const expandPdf = (index) => {
      showPdfIndex.value = index
    }

    const closePdf = () => {
      showPdfIndex.value = null
    }

    // Watch for changes in selectedCard.document
    watch(() => props.selectedCard.document, (newDocs, oldDocs) => {
      console.log('Documents changed:', newDocs)
      if (newDocs) {
        pdfThumbnails.value = new Array(newDocs.length).fill('')
        newDocs.forEach((doc, index) => {
          if (doc.url) {
            console.log(`Processing URL at index ${index}: ${doc.url}`)
            if (!isImage(doc.url) && doc.url.endsWith('.pdf')) {
              generatePdfThumbnail(doc.url, index)
            }
          }
        })
      } else {
        pdfThumbnails.value = []
      }
    }, { immediate: true, deep: true })

    return {
      closeDialog,
      handleSave,
      handleDelete,
      addAction,
      addDocument,
      addAdvertisement,
      removeAction,
      removeDocument,
      removeAdvertisement,
      updateDocumentUrl,
      pdfThumbnails,
      showPdfIndex,
      isImage,
      expandPdf,
      closePdf,
    }
  },
}
</script>

<style scoped>
.dialog-wrapper {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 2000;
}

.dialog-content {
  background: white;
  padding: 20px;
  width: 90%;
  max-width: 1200px;
  height: 90vh;
  max-height: 90vh;
  overflow-y: auto;
  position: relative;
  box-sizing: border-box;
  z-index: 2001;
}

.close-button {
  position: absolute;
  top: 10px;
  right: 10px;
  background: none;
  border: none;
  font-size: 20px;
  cursor: pointer;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0;
}

.action-buttons {
  display: flex;
  justify-content: space-around;
  align-items: center;
  margin-top: 10px;
}

.nice-button {
  padding: 8px 12px;
  background-color: #4CAF50;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.nice-button:hover {
  background-color: #45a049;
}

.e-btn {
  padding: 8px 12px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  margin: 0 5px;
}

.e-btn.e-primary {
  background-color: #007bff;
  color: white;
}

.e-btn:hover {
  background-color: #e0e0e0;
}

.lease-fields {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 20px;
}

.lease-fields label {
  font-weight: bold;
}

.lease-fields input {
  padding: 8px;
  border: 1px solid #ccc;
  border-radius: 4px;
}

.thumbnails-container {
  margin-top: 20px;
}

.thumbnails {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.thumbnail-wrapper {
  text-align: center;
}

.thumbnail {
  max-width: 100px;
  height: auto;
  cursor: pointer;
}

.pdf-viewer {
  margin-top: 20px;
}

.close-pdf-btn {
  margin-top: 10px;
  padding: 4px 8px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.close-pdf-btn:hover {
  background-color: #0056b3;
}
</style>