})

// Define reactive data
const dataSource1 = ["buyer", "seller", "rent", "owner", "lease", "tenanted", "project_buyer", "project_seller", "task"]
const dataSource2 = ["Alyssa", "Ashton", "Alvin", "Unassigned"]
const dataSource3 = [0, 1, 2, 3, 4, 5, 6, 7]
const dataSource4 = ["Advertisement", "Collect", "Closing", "Done", "Exclusive", "Follow_up", "Pending", "Photo", "Prepare", "Qualify", "Reject", "Research", "Review", "Schedule", "Screening", "Share", "Signing", "Visit", "iProperty", "Mudah", "Facebook", "Signage"]
const dataSource6 = ["Alyssa H", "Ashton H", "Alvin S", "Alvin H"]

// Define methods
const applyTemplate = (event) => {
  const selectedIndex = event.target.value
  if (selectedIndex !== "") {
    props.card.info = tenantProfiles[selectedIndex][2]
    event.target.value = ""
  }
}

const removeExampleData = () => {
  if (props.card.info) {
    props.card.info = props.card.info.replace(/^(.+?:).*$/gm, '$1 ')
  }
}
</script>

