import { createApp } from 'vue';
import './style.css'; // Your custom CSS
import App from './App.vue';

// Import Vuetify and Vuetify CSS
import { createVuetify } from 'vuetify';
import 'vuetify/styles'; // Vuetify 3 styles (recommended)

// Import Material Design Icons
import '@mdi/font/css/materialdesignicons.css'; // MDI icons

import { GlobalWorkerOptions } from 'pdfjs-dist/build/pdf';
import { registerLicense } from '@syncfusion/ej2-base';
import * as components from 'vuetify/components';
import * as directives from 'vuetify/directives';
import { createPinia } from 'pinia';

// Apollo Client imports
import { ApolloClient, InMemoryCache, HttpLink } from '@apollo/client/core';
import { provideApolloClient } from '@vue/apollo-composable';

// Import Vue Router
import router from './router';

registerLicense(
  'ORg4AjUWIQA/Gnt2V1hhQ1JNfVddX2BWfFN0RnNYfVR0d19DZUwx0X1dQ19gSX1RckRhXXtdd3xTRWU='
);

// Set PDF.js worker source
GlobalWorkerOptions.workerSrc = 'node_modules/pdfjs-dist/build/pdf.worker.min.js';

// Configure Vuetify with icons
const vuetify = createVuetify({
  components,
  directives,
});

const pinia = createPinia();

// Create Apollo Client instance
const apolloClient = new ApolloClient({
  link: new HttpLink({
    uri: 'https://sp412b-763ef468411d.herokuapp.com/graphql', // Replace with your actual GraphQL endpoint
  }),
  cache: new InMemoryCache(),
});

// Create Vue app instance
const app = createApp(App);

// Use plugins
app.use(vuetify); // Use Vuetify
app.use(pinia);   // Use Pinia
app.use(router);  // Use Vue Router

// Provide Apollo Client to the app
app.provide('apolloClient', apolloClient);

// Use provideApolloClient for @vue/apollo-composable
provideApolloClient(apolloClient);

app.config.globalProperties.cleanPhoneNumber = function(phoneNumber) {
  return phoneNumber.replace(/[\s-]/g, '');
};

// Mount the app
app.mount('#app');