<template>
    <v-dialog :model-value="modelValue" max-width="600" @update:modelValue="$emit('update:modelValue', $event)">
        <v-card>
            <v-card-title>Edit Todo</v-card-title>
            <v-card-text>
                <v-form @submit.prevent="handleSave">
                    <v-row>
                        <v-col cols="12">
                            <v-text-field v-model="localTodo.name" label="Task Name" outlined
                                :rules="[v => !!v || 'Name is required']"></v-text-field>
                        </v-col>
                        <v-col cols="12">
                            <v-textarea v-model="localTodo.description" label="Description" outlined
                                rows="3"></v-textarea>
                        </v-col>
                        <v-col cols="6">
                            <v-select v-model="localTodo.priority" :items="[1, 2, 3, 4, 5]" label="Priority"
                                outlined></v-select>
                        </v-col>
                        <v-col cols="6">
                            <v-select v-model="localTodo.assignedTo" :items="userOptions" label="Assign To"
                                outlined></v-select>
                        </v-col>
                        <v-col cols="6">
                            <v-menu v-model="startDateMenu" :close-on-content-click="false">
                                <template v-slot:activator="{ props: activatorProps }">
                                    <v-text-field v-model="startDateFormatted" label="Start Date"
                                        prepend-icon="mdi-calendar" readonly v-bind="activatorProps"
                                        outlined></v-text-field>
                                </template>
                                <v-date-picker v-model="startDate"
                                    @update:modelValue="startDateMenu = false"></v-date-picker>
                            </v-menu>
                        </v-col>
                        <v-col cols="6">
                            <v-menu v-model="dateMenu" :close-on-content-click="false">
                                <template v-slot:activator="{ props: activatorProps }">
                                    <v-text-field v-model="dueDateFormatted" label="Due Date"
                                        prepend-icon="mdi-calendar" readonly v-bind="activatorProps"
                                        outlined></v-text-field>
                                </template>
                                <v-date-picker v-model="dueDate" @update:modelValue="dateMenu = false"></v-date-picker>
                            </v-menu>
                        </v-col>
                        <v-col cols="6">
                            <v-menu v-model="timeMenu" :close-on-content-click="false">
                                <template v-slot:activator="{ props: activatorProps }">
                                    <v-text-field v-model="dueTime" label="Due Time" prepend-icon="mdi-clock-outline"
                                        readonly v-bind="activatorProps" outlined></v-text-field>
                                </template>
                                <v-time-picker v-model="dueTime" format="24hr"
                                    @update:modelValue="timeMenu = false"></v-time-picker>
                            </v-menu>
                        </v-col>
                        <v-col cols="12">
                            <v-select v-model="localTodo.category" :items="categoryOptions" label="Category"
                                outlined></v-select>
                        </v-col>
                        <v-col cols="12" class="d-flex justify-end">
                            <v-btn color="primary" type="submit" :loading="loading" class="short-btn">Save</v-btn>
                            <v-btn color="error" @click="handleCancel" class="short-btn ml-2">Cancel</v-btn>
                        </v-col>
                    </v-row>
                </v-form>
            </v-card-text>
        </v-card>
    </v-dialog>
</template>

<script setup>
import { ref, computed, watch } from 'vue';
import { VTimePicker } from 'vuetify/labs/VTimePicker';

const props = defineProps({
    modelValue: Boolean,
    todo: {
        type: Object,
        required: true,
    },
    categoryOptions: {
        type: Array,
        default: () => [],
    },
    userOptions: {
        type: Array,
        default: () => [],
    },
    loading: Boolean,
});

const emit = defineEmits(['update:modelValue', 'save', 'cancel']);

const localTodo = ref({ ...props.todo, description: props.todo.description || '' });
const startDate = ref(null);
const dueDate = ref(null);
const dueTime = ref('12:00');
const startDateMenu = ref(false);
const dateMenu = ref(false);
const timeMenu = ref(false);

// Watch props.todo to sync localTodo whenever it changes
watch(() => props.todo, (newTodo) => {
    localTodo.value = { ...newTodo, description: newTodo.description || '' };
    if (newTodo.startDate) {
        const date = new Date(newTodo.startDate);
        if (!isNaN(date.getTime())) {
            startDate.value = date.toISOString().split('T')[0]; // YYYY-MM-DD
        } else {
            startDate.value = null;
        }
    } else {
        startDate.value = null;
    }
    if (newTodo.dueDate) {
        const date = new Date(newTodo.dueDate);
        if (!isNaN(date.getTime())) {
            dueDate.value = date.toISOString().split('T')[0]; // YYYY-MM-DD
            dueTime.value =
                String(date.getHours()).padStart(2, '0') + ':' +
                String(date.getMinutes()).padStart(2, '0');
        } else {
            dueDate.value = null;
            dueTime.value = '12:00';
        }
    } else {
        dueDate.value = null;
        dueTime.value = '12:00';
    }
}, { immediate: true, deep: true });

const startDateFormatted = computed(() => {
    if (!startDate.value) return null;
    const date = new Date(startDate.value);
    return date.toLocaleDateString('en-GB');
});

const dueDateFormatted = computed(() => {
    if (!dueDate.value) return null;
    const date = new Date(dueDate.value);
    return date.toLocaleDateString('en-GB');
});

const handleSave = () => {
    let fullStartDate = null;
    let fullDueDate = null;

    if (startDate.value) {
        let startDateStr = startDate.value;
        if (typeof startDateStr !== 'string') {
            console.error('startDate.value is not a string:', startDateStr);
            startDateStr = startDateStr instanceof Date ? startDateStr.toISOString().split('T')[0] : null;
        }
        if (startDateStr) {
            const [year, month, day] = startDateStr.split('-');
            fullStartDate = new Date(
                parseInt(year),
                parseInt(month) - 1,
                parseInt(day)
            ).toISOString();
        }
    }

    if (dueDate.value && dueTime.value) {
        let dueDateStr = dueDate.value;
        if (typeof dueDateStr !== 'string') {
            console.error('dueDate.value is not a string:', dueDateStr);
            dueDateStr = dueDateStr instanceof Date ? dueDateStr.toISOString().split('T')[0] : null;
        }
        if (dueDateStr) {
            const [year, month, day] = dueDateStr.split('-');
            const [hours, minutes] = dueTime.value.split(':');
            fullDueDate = new Date(
                parseInt(year),
                parseInt(month) - 1,
                parseInt(day),
                parseInt(hours),
                parseInt(minutes)
            ).toISOString();
        }
    }




    emit('save', {
        ...localTodo.value,
        startDate: fullStartDate,
        dueDate: fullDueDate,
        description: localTodo.value.description // Should already be present
    });
};


const handleCancel = () => {
    emit('cancel');
    emit('update:modelValue', false);
};
</script>

<style scoped>
.v-dialog {
    transition: all 0.3s ease;
}

.short-btn {
    min-width: 80px !important;
    width: 80px;
    padding-left: 8px;
    padding-right: 8px;
}
</style>