<template>
  <v-dialog :model-value="modelValue" @update:modelValue="updateDialog" max-width="1800px" persistent
    class="detailed-records-dialog">
    <v-card class="dialog-card">
      <v-card-title class="dialog-header">
        <span class="headline">Detailed Records - {{ dialogTitle }}</span>
        <v-spacer />
        <v-btn icon color="green" @click="addNewRecord" aria-label="Add new record">
          <v-icon>mdi-plus</v-icon>
        </v-btn>
        <v-btn color="primary" text @click="updateDialog(false)">Close</v-btn>
      </v-card-title>

      <v-card-text class="dialog-content">
        <EditContactForm v-if="showEditForm && currentContact" v-bind="editFormProps" @save="saveContact"
          @cancel="cancelEdit" @delete="confirmDelete" @next="nextValidContact" />

        <div v-else class="table-wrapper">
          <table class="records-table">
            <thead>
              <tr>
                <th class="checkbox-column">
                  <v-checkbox v-model="selectAll" hide-details density="compact" @update:modelValue="toggleSelectAll" />
                </th>
                <th v-for="header in detailHeaders" :key="header.value" @click="sortTable(header.value)">
                  <div class="header-content">
                    {{ header.title }}
                    <v-icon v-if="sortBy[0].key === header.value" small>
                      {{ sortBy[0].order === 'desc' ? 'mdi-arrow-down' : 'mdi-arrow-up' }}
                    </v-icon>
                  </div>
                </th>
                <th class="actions-column">Actions</th>
              </tr>
            </thead>
            <tbody>
              <tr v-for="(item, index) in sortedRecords" :key="item.id" :class="{ 'today-row': isUpdatedToday(item.updatedAt) }">
                <td>
                  <v-checkbox v-model="selectedRecords" :value="item" hide-details density="compact" />
                </td>
                <td v-for="header in detailHeaders" :key="header.value">
                  <template v-if="header.value === 'id'">
                    <v-btn text small @click="editContact(item, index)"
                      :class="{ 'updated-today': isUpdatedToday(item.updatedAt) }">
                      {{ item.id }}
                    </v-btn>
                  </template>
                  <template v-else-if="header.value === 'updatedAt' || header.value === 'dialedDate'">
                    {{ formatDate(item[header.value]) }}
                  </template>
                  <template v-else>
                    {{ item[header.value] || 'N/A' }}
                  </template>
                </td>
                <td>
                  <v-btn small text @click="editRecord(item)"><v-icon>mdi-pencil</v-icon></v-btn>
                  <v-btn small text @click="fullEditRecord(item)"><v-icon>mdi-file-document-edit</v-icon></v-btn>
                  <v-btn small text color="red" @click="deleteRecord(item)"><v-icon>mdi-delete</v-icon></v-btn>
                </td>
              </tr>
            </tbody>
          </table>
        </div>

        <v-dialog v-model="editDialog" max-width="500px" class="edit-dialog">
          <v-card>
            <v-card-title class="edit-header">
              {{ editMode ? 'Edit' : 'Add' }} Record
            </v-card-title>
            <v-card-text>
              <v-form v-model="valid">
                <v-text-field v-model="editedItem.id" label="ID" :disabled="editMode" />
                <v-text-field v-model="editedItem.dialedDate" label="Dialed Date" type="date" />
                <v-select v-model="editedItem.project" :items="projectOptions" label="Project" />
                <v-text-field v-model="editedItem.name" label="Name" />
                <v-text-field v-model="editedItem.phoneNumber" label="Phone Number" type="tel" />
                <v-select v-model="editedItem.language" :items="languageOptions" label="Language" />
                <v-textarea v-model="editedItem.interaction" label="Interaction" rows="3" auto-grow />
                <v-text-field v-model="editedItem.assignee" label="Assignee" />
                <v-text-field v-model="editedItem.rating" label="Rating" type="number" min="0" max="5" />
                <v-select v-model="editedItem.status" :items="statusOptions" label="Status" />
                <v-text-field v-model="editedItem.requestType" label="Request Type" />
              </v-form>
            </v-card-text>
            <v-card-actions>
              <v-spacer />
              <v-btn text @click="closeEditDialog">Cancel</v-btn>
              <v-btn color="primary" text @click="saveRecord" :disabled="!valid">Save</v-btn>
            </v-card-actions>
          </v-card>
        </v-dialog>

        <v-dialog v-model="showFullEditDialog" :max-width="'90vw'" :max-height="'90vh'" z-index="2000"
          class="full-edit-dialog">
          <CardDetailsDialog :isSaveDialogVisible="showFullEditDialog" :selectedCard="selectedFullEditRecord"
            taskMode="edit" @close-dialog="closeFullEditDialog" @save-changes="saveFullEditChanges" />
        </v-dialog>
      </v-card-text>

      <v-card-actions class="dialog-footer">
        <v-btn color="red" text @click="deleteSelectedRecords" :disabled="!selectedRecords.length">
          Delete Selected ({{ selectedRecords.length }})
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script setup>
import { ref, computed } from 'vue';
import EditContactForm from '@/components/EditContactForm.vue';
import CardDetailsDialog from '@/components/CardDetailsDialog.vue';

const props = defineProps({
  modelValue: Boolean,
  dialogTitle: String,
  detailedRecords: Array,
});

const emit = defineEmits(['update:modelValue', 'updateRecords']);

const editDialog = ref(false);
const editMode = ref(false);
const valid = ref(true);
const showEditForm = ref(false);
const selectedIndex = ref(-1);
const currentContact = ref(null);
const selectedRecords = ref([]);
const sortBy = ref([{ key: 'updatedAt', order: 'desc' }]);
const showFullEditDialog = ref(false);
const selectedFullEditRecord = ref(null);

const defaultItem = {
  id: '',
  dialedDate: '',
  project: '',
  name: '',
  phoneNumber: '',
  language: '',
  interaction: '',
  assignee: '',
  rating: 0,
  status: '',
  requestType: '',
  updatedAt: '', // Ensure updatedAt is part of the default structure
};

const editedItem = ref({ ...defaultItem });

const projectOptions = ['Project A', 'Project B', 'Project C'];
const languageOptions = ['English', 'Spanish', 'French'];
const statusOptions = ['Pending', 'In Progress', 'Completed'];

const detailHeaders = [
  { title: 'Phone ID', value: 'phoneId' },
  { title: 'ID', value: 'id' },
  { title: 'Updated', value: 'updatedAt' },
  { title: 'Dialed', value: 'dialedDate' },
  { title: 'Project', value: 'project' },
  { title: 'Name', value: 'name' },
  { title: 'Phone', value: 'phoneNumber' },
  { title: 'Lang', value: 'language' },
  { title: 'Interaction', value: 'interaction' },
  { title: 'Status', value: 'status' },
  { title: 'Assignee', value: 'assignee' },
  { title: 'Rating', value: 'rating' },
  { title: 'Request', value: 'requestType' },
];

const editFormProps = computed(() => ({
  index: selectedIndex.value,
  contacts: props.detailedRecords,
  contact: currentContact.value,
  selectedUser: '',
  selectedPhoneId: '',
}));

const sortedRecords = computed(() => {
  const records = [...props.detailedRecords];
  const [sort] = sortBy.value;
  return records.sort((a, b) => {
    const valA = a[sort.key] ?? '';
    const valB = b[sort.key] ?? '';
    return sort.order === 'desc'
      ? String(valB).localeCompare(String(valA))
      : String(valA).localeCompare(String(valB));
  });
});

const selectAll = computed({
  get: () => selectedRecords.value.length === props.detailedRecords.length,
  set: (value) => {
    selectedRecords.value = value ? [...props.detailedRecords] : [];
  },
});

// Methods
const updateDialog = (value) => emit('update:modelValue', value);

const addNewRecord = () => {
  editMode.value = false;
  editedItem.value = { ...defaultItem };
  editDialog.value = true;
};

const editRecord = (item) => {
  editMode.value = true;
  editedItem.value = { ...item, dialedDate: formatDate(item.dialedDate) };
  editDialog.value = true;
};

const fullEditRecord = (item) => {
  selectedFullEditRecord.value = { ...item };
  showFullEditDialog.value = true;
};

const closeFullEditDialog = () => {
  showFullEditDialog.value = false;
  selectedFullEditRecord.value = null;
};

const saveFullEditChanges = (updatedRecord) => {
  updatedRecord.updatedAt = new Date().toISOString(); // Set current date on save
  const updatedRecords = props.detailedRecords.map(r =>
    r.id === updatedRecord.id ? updatedRecord : r
  );
  emit('updateRecords', updatedRecords, updatedRecord);
  closeFullEditDialog();
};

const saveRecord = () => {
  editedItem.value.updatedAt = new Date().toISOString(); // Set current date on save
  const updatedRecords = editMode.value
    ? props.detailedRecords.map(r => r.id === editedItem.value.id ? editedItem.value : r)
    : [...props.detailedRecords, { ...editedItem.value, id: Date.now().toString() }];
  emit('updateRecords', updatedRecords, editedItem.value);
  editDialog.value = false;
};

const deleteRecord = (item) => {
  if (confirm('Delete this record?')) {
    emit('updateRecords', props.detailedRecords.filter(r => r.id !== item.id), item);
  }
};

const deleteSelectedRecords = () => {
  if (confirm(`Delete ${selectedRecords.value.length} records?`)) {
    emit('updateRecords', props.detailedRecords.filter(r => !selectedRecords.value.includes(r)), null);
    selectedRecords.value = [];
  }
};

const closeEditDialog = () => {
  editDialog.value = false;
};

const editContact = (contact, index) => {
  selectedIndex.value = index;
  currentContact.value = contact;
  showEditForm.value = true;
};

const saveContact = (updatedContact) => {
  updatedContact.updatedAt = new Date().toISOString(); // Set current date on save
  const updatedRecords = props.detailedRecords.map((r, i) =>
    i === selectedIndex.value ? updatedContact : r
  );
  emit('updateRecords', updatedRecords, updatedContact);
  showEditForm.value = false;
};

const cancelEdit = () => {
  showEditForm.value = false;
};

const confirmDelete = (contact) => {
  if (confirm('Are you sure you want to delete this contact?')) {
    emit('updateRecords', props.detailedRecords.filter(r => r.id !== contact.id), contact);
    showEditForm.value = false;
  }
};

const nextValidContact = () => {
  return props.detailedRecords.slice(selectedIndex.value + 1)
    .find(r => r.status !== 'Registered');
};

const formatDate = (date) => date?.split('T')[0] || 'N/A';

const isUpdatedToday = (date) => {
  if (!date) return false;
  const today = new Date(); // Dynamic current date
  const recordDate = new Date(date);
  return today.toDateString() === recordDate.toDateString();
};

const sortTable = (key) => {
  const [current] = sortBy.value;
  sortBy.value = [{
    key,
    order: current.key === key && current.order === 'desc' ? 'asc' : 'desc'
  }];
};

const toggleSelectAll = (value) => {
  selectedRecords.value = value ? [...props.detailedRecords] : [];
};
</script>

<style scoped>
.detailed-records-dialog {
  font-family: 'Roboto', sans-serif;
  z-index: 1000;
}

.dialog-card {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.dialog-content {
  flex: 1;
  padding: 20px;
  overflow-y: auto;
}

.full-edit-dialog {
  z-index: 2000 !important;
}

:deep(.v-overlay__content) {
  height: 95vh;
  max-height: 95vh;
  width: 95vw;
  max-width: 95vw;
}

:deep(.full-edit-dialog .v-overlay__content) {
  height: 90vh;
  max-height: 90vh;
  width: 90vw;
  max-width: 90vw;
}

.today-row {
  background-color: #e0f7fa; /* Light cyan background for today’s date */
  font-weight: bold;
}

.updated-today {
  color: green; /* Existing style for the ID button */
}
</style>