<script setup>
import { ref, onMounted } from 'vue';
import { useRouter } from 'vue-router';
import { useUserStore } from '@/stores/user';
import { messagingPromise, getToken, deleteToken, onMessage, requestPermission } from '@/firebase';
import PhoneIdSelector from './components/PhoneIdSelector.vue';
import AssigneeIdSelector from './components/AssigneeIdSelector.vue';


const router = useRouter();
const userStore = useUserStore();

// Reactive state
const username = ref('');
const password = ref('');
const loginError = ref('');
const showPassword = ref(false);
const sidebarOpen = ref(false);
const isLoggedIn = ref(false);
const notifications = ref([]);

// Hardcoded users for demo purposes
const users = ref([
  { name: 'Alyssa', password: 'trewq' },
  { name: 'Alvin', password: 'trewq' },
  { name: 'Ashton', password: 'trewq' },
]);

// Validate credentials
const validateCredentials = () => {
  return users.value.some(u => 
    u.name === username.value && 
    u.password === password.value.split('').reverse().join('')
  );
};

// Login function
const login = async () => {
  if (!validateCredentials()) {
    loginError.value = 'Invalid credentials';
    return;
  }

  try {
    isLoggedIn.value = true;
    userStore.setUser(username.value);
    localStorage.setItem('authToken', btoa(username.value));
    
    await setupFCM();
  } catch (error) {
    loginError.value = 'Login failed';
    console.error('Login error:', error);
  }
};

// Setup Firebase Cloud Messaging
const setupFCM = async () => {
  try {
    const messaging = await messagingPromise;
    if (!messaging) {
      console.warn('FCM not available: Messaging not initialized or not supported');
      return;
    }

    const token = await requestPermission();
    if (token) {
      await storeFCMToken(token);
      console.log('FCM Token:', token);
    } else {
      console.log('No FCM token obtained');
    }

    // Handle foreground messages
    onMessage(messaging, (payload) => {
      console.log('Foreground message received:', payload);
      notifications.value.push({
        title: payload.notification?.title || 'No Title',
        body: payload.notification?.body || 'No Body'
      });
    });
  } catch (error) {
    console.error('FCM setup failed:', error);
  }
};

// Logout function
const logout = async () => {
  try {
    const messaging = await messagingPromise;
    if (messaging) {
      await deleteToken(messaging);
      console.log('FCM token deleted');
    }
  } catch (error) {
    console.error('Error deleting token:', error);
  }
  
  userStore.clearUser();
  localStorage.removeItem('authToken');
  isLoggedIn.value = false;
  notifications.value = [];
};

// Remove notification
const removeNotification = (index) => {
  notifications.value.splice(index, 1);
};

// Navigation helper
const navigateTo = (route) => {
  router.push({ name: route });
};

// Toggle sidebar
const toggleSidebar = () => {
  sidebarOpen.value = !sidebarOpen.value;
};

// Service Worker Registration
onMounted(async () => {
  if ('serviceWorker' in navigator) {
    try {
      const registration = await navigator.serviceWorker.register('/firebase-messaging-sw.js');
      console.log('Service Worker registered:', registration);
    } catch (error) {
      console.error('Service Worker registration failed:', error);
    }
  }

  // Check if already logged in
  const authToken = localStorage.getItem('authToken');
  console.log('onMounted authToken:', authToken);
  if (authToken) {
    const decodedUser = atob(authToken);
    if (users.value.some(u => u.name === decodedUser)) {
      isLoggedIn.value = true;
      userStore.setUser(decodedUser);
      try {
        await setupFCM(); // Only proceed if token is valid
      } catch (error) {
        console.error('FCM setup failed, but keeping user logged in:', error);
        // Don’t reset isLoggedIn here
      }
    } else {
      console.log('Invalid authToken, logging out');
      logout();
    }
  }
});

// Store FCM token (placeholder - implement as needed)
const storeFCMToken = async (token) => {
  console.log('Storing FCM token:', token);
  // Add your logic to send the token to your server here
};
</script>

