// src/utils/todoService.js
import { gql } from '@apollo/client';
import client from '../apollo-client';

// Update the UPDATE_TODO mutation to include description
export const fetchNotes = async (requestType, language) => {
  try {
    const { data } = await client.query({
      query: gql`
        query Notes($requestType: String, $language: String) {
          notes(filters: { 
            requestType: { eq: $requestType }
            language: { eq: $language }
          }) {
            data {
              id
              attributes {
                title
                content
                language
                requestType
                createdAt
                updatedAt
              }
            }
          }
        }
      `,
      variables: { requestType, language }, // Pass both requestType and language as variables
      fetchPolicy: 'network-only'
    });
    
    // Map the response data to a simpler format
    return data.notes.data.map(note => ({
      id: note.id,
      title: note.attributes.title,
      content: note.attributes.content,
      language: note.attributes.language,
      category: note.attributes.category,
      requestType: note.attributes.requestType,
      createdAt: note.attributes.createdAt,
      updatedAt: note.attributes.updatedAt
    }));
    
  } catch (error) {
    console.error('Error fetching notes:', error);
    throw new Error('Failed to fetch notes');
  }
};


// TODOS_QUERY already includes description
export const TODOS_QUERY = gql`

  query Todos {

 todos(pagination: { limit: 1000 }, sort: ["assignedTo:desc,priority:desc,done"]) {
    data {
        id
        attributes {
          name
          done
          priority
          startDate
          dueDate
          category
          description
          markedForDelete
          assignedTo
        }
      }
    }
  }
`;

// Update CREATE_TODO to include description
export const CREATE_TODO = gql`
  mutation CreateTodo(
    $name: String!
    $priority: Int
    $startDate: DateTime
    $dueDate: DateTime
    $category: String
    $assignedTo: String
    $description: String
  ) {
    createTodo(data: { 
      name: $name
      priority: $priority
      startDate: $startDate
      dueDate: $dueDate
      category: $category
      assignedTo: $assignedTo
      done: false
      description: $description
    }) {
      data {
        id
        attributes {
          name
          done
          priority
          startDate
          dueDate
          category
          description
          markedForDelete
          assignedTo
        }
      }
    }
  }
`;

// DELETE_TODO remains unchanged
export const DELETE_TODO = gql`
  mutation DeleteTodo($id: ID!) {
    deleteTodo(id: $id) {
      data {
        id
      }
    }
  }
`;

export async function fetchTodos() {
  try {
    const { data } = await client.query({
      query: TODOS_QUERY,
      fetchPolicy: 'network-only'
    });
    return data.todos.data.map(todo => ({
      id: todo.id,
      name: todo.attributes.name,
      done: todo.attributes.done,
      priority: todo.attributes.priority,
      startDate: todo.attributes.startDate,
      dueDate: todo.attributes.dueDate,
      category: todo.attributes.category,
      description: todo.attributes.description || '', // Ensure description is included with fallback
      markedForDelete: todo.attributes.markedForDelete,
      assignedTo: todo.attributes.assignedTo || 'All'
    }));
  } catch (error) {
    console.error('Error fetching todos:', error);
    throw error;
  }
}

export async function createTodo({ name, priority, startDate, dueDate, category, assignedTo, description }) {
  try {
    const variables = {
      name,
      priority: priority || 1,
      startDate: startDate || null,
      dueDate: dueDate || null,
      category: category || null,
      assignedTo: assignedTo !== 'All' ? assignedTo : null,
      description: description || null // Include description in variables
    };

    console.log('Creating todo with:', variables);

    const { data } = await client.mutate({
      mutation: CREATE_TODO,
      variables
    });

    const createdTodo = {
      id: data.createTodo.data.id,
      ...data.createTodo.data.attributes,
      startDate: data.createTodo.data.attributes.startDate,
      assignedTo: data.createTodo.data.attributes.assignedTo || 'All',
      description: data.createTodo.data.attributes.description || '' // Ensure description is returned
    };

    console.log('Created todo:', createdTodo);
    return createdTodo;
  } catch (error) {
    console.error('Error creating todo:', error);
    throw error;
  }
}

// src/utils/todoService.js (relevant parts only)


export const UPDATE_TODO = gql`
  mutation UpdateTodo(
    $id: ID!
    $name: String
    $priority: Int
    $startDate: DateTime
    $dueDate: DateTime
    $category: String
    $assignedTo: String
    $done: Boolean
    $markedForDelete: Boolean
    $description: String
  ) {
    updateTodo(
      id: $id
      data: { 
        name: $name
        priority: $priority
        startDate: $startDate
        dueDate: $dueDate
        category: $category
        assignedTo: $assignedTo
        done: $done
        markedForDelete: $markedForDelete
        description: $description
      }
    ) {
      data {
        id
        attributes {
          name
          done
          priority
          startDate
          dueDate
          category
          description
          markedForDelete
          assignedTo
        }
      }
    }
  }
`;

export async function updateTodo(id, updates) {
  try {
    const variables = { 
      id: String(id),
      ...updates
    };

    if (variables.assignedTo === 'All') {
      variables.assignedTo = null;
    }

    // Ensure description is included
    variables.description = variables.description?.trim() || null;  // Handle empty strings

    if (variables.startDate && typeof variables.startDate === 'string') {
      const [datePart] = variables.startDate.split('T');
      const [year, month, day] = datePart.split('-');
      variables.startDate = new Date(parseInt(year), parseInt(month) - 1, parseInt(day)).toISOString();
    }
    if (variables.dueDate && typeof variables.dueDate === 'string') {
      const [datePart, timePart] = variables.dueDate.split('T');
      const [year, month, day] = datePart.split('-');
      const [hours, minutes] = timePart.split(':');
      variables.dueDate = new Date(parseInt(year), parseInt(month) - 1, parseInt(day), parseInt(hours), parseInt(minutes)).toISOString();
    }

    console.log('Updating todo with:', variables);

    const { data } = await client.mutate({
      mutation: UPDATE_TODO,
      variables
    });

    const updatedTodo = {
      id: data.updateTodo.data.id,
      ...data.updateTodo.data.attributes,
      startDate: data.updateTodo.data.attributes.startDate,
      assignedTo: data.updateTodo.data.attributes.assignedTo || 'All',
      description: data.updateTodo.data.attributes.description || ''
    };

    console.log('Updated todo:', updatedTodo);
    return updatedTodo;
  } catch (error) {
    console.error('Error updating todo:', error);
    throw error;
  }
}

// deleteTodo remains unchanged
export async function deleteTodo(id) {
  try {
    const { data } = await client.mutate({
      mutation: DELETE_TODO,
      variables: { id }
    });
    return data.deleteTodo.data.id;
  } catch (error) {
    console.error('Error deleting todo:', error);
    throw error;
  }
}