// LeadStatsCalendar.vue
<template>
  <div class="calendar-container">
    <div v-if="loading" class="loading-state">
      Loading calendar data...
    </div>
    
    <div v-else-if="error" class="error-state">
      {{ error }}
    </div>
    
    <div v-else>
      <h1>Lead Call Statistics</h1>
      
      <div class="calendar-header">
        <button @click="previousMonth" class="nav-button">&lt;</button>
        <h2>{{ currentMonthYear }}</h2>
        <button @click="nextMonth" class="nav-button">&gt;</button>
      </div>
      
      <div class="stats-summary">
        <div class="stat-item">
          <span class="stat-label">Monthly Calls:</span>
          <span class="stat-value">{{ monthlyStats.totalCalls }}</span>
        </div>
        <div class="stat-item">
          <span class="stat-label">High Rated (>3):</span>
          <span class="stat-value">{{ monthlyStats.highRated }}</span>
        </div>
      </div>

      <div class="weekday-header">
        <div v-for="day in weekDays" :key="day" class="weekday">{{ day }}</div>
      </div>

      <div class="calendar-grid">
        <div 
          v-for="{ date, stats } in calendarDays" 
          :key="date.toISOString()" 
          class="calendar-day"
          :class="{
            'current-month': isCurrentMonth(date),
            'has-calls': stats && stats.totalCalls > 0
          }"
        >
          <div class="date">{{ date.getDate() }}</div>
          <div v-if="stats" class="stats">
            <div class="total-calls" :class="getCallVolumeClass(stats.totalCalls)">
              Calls: {{ stats.totalCalls }}
            </div>
            <div class="high-rated" v-if="stats.totalCalls > 0">
              Lead: {{ stats.highRated }}
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { gql } from '@apollo/client/core';
import client from '../apollo-client';

export default {
  name: 'LeadStatsCalendar',
  
  data() {
    return {
      currentDate: new Date(),
      weekDays: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'],
      leads: [],
      loading: true,
      error: null
    }
  },

  computed: {
    currentMonthYear() {
      return new Intl.DateTimeFormat('en-US', {
        month: 'long',
        year: 'numeric'
      }).format(this.currentDate)
    },

    monthlyStats() {
      const totalCalls = this.leads.filter(lead => {
        const callDate = new Date(lead.dialedDate ||  lead.createAt )
        return this.isCurrentMonth(callDate)
      }).length

      const highRated = this.leads.filter(lead => {
        const callDate = new Date(lead.dialedDate ||  lead.createAt )
        return this.isCurrentMonth(callDate) && lead.rating > 3
      }).length

      return { totalCalls, highRated }
    },

    calendarDays() {
      const year = this.currentDate.getFullYear()
      const month = this.currentDate.getMonth()
      
      const firstDay = new Date(year, month, 1)
      const lastDay = new Date(year, month + 1, 0)
      
      const days = []
      
      // Add padding days from previous month
      const padding = firstDay.getDay()
      const prevMonth = new Date(year, month, 0)
      for (let i = padding - 1; i >= 0; i--) {
        days.push({
          date: new Date(year, month - 1, prevMonth.getDate() - i),
          stats: this.getStatsForDate(new Date(year, month - 1, prevMonth.getDate() - i))
        })
      }
      
      // Add current month days with stats
      for (let i = 1; i <= lastDay.getDate(); i++) {
        const currentDate = new Date(year, month, i)
        days.push({
          date: currentDate,
          stats: this.getStatsForDate(currentDate)
        })
      }
      
      // Add padding days for next month
      const remainingDays = 42 - days.length // 6 rows * 7 days
      for (let i = 1; i <= remainingDays; i++) {
        days.push({
          date: new Date(year, month + 1, i),
          stats: this.getStatsForDate(new Date(year, month + 1, i))
        })
      }
      
      return days
    }
  },

  methods: {
    async fetchLeads() {
      this.loading = true
      this.error = null
      
      try {
        const startDate = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth(), 1)
        const endDate = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth() + 1, 0)
        
        const { data } = await client.query({
          query: gql`
       query GetLeadsForMonth($startDate: DateTime!, $endDate: DateTime!) {
  leads(
    filters: {
      and: [
    
        { or: [
            { createdAt: { gte: $startDate, lte: $endDate } }
            { dialedDate: { gte: $startDate, lte: $endDate } }
           { updatedAt: { gte: $startDate, lte: $endDate } }
          
          ] 
        }
      ]
    }
    pagination: { limit: 1000 }
  ) {
    data {
      id
      attributes {
        createdAt
        updatedAt
        dialedDate
        lastCall
        rating
        phoneNumber
        name
        stage
        assignee
      }
    }
  }
}
          `,
          variables: {
            startDate: startDate.toISOString(),
            endDate: endDate.toISOString()
          },
          fetchPolicy: 'no-cache',
        })

        this.leads = data.leads.data.map(lead => ({
          id: lead.id,
          ...lead.attributes
        }))
      } catch (err) {
        this.error = 'Failed to load calendar data. Please try again later.'
        console.error('Error fetching lead data:', err)
      } finally {
        this.loading = false
      }
    },

    isCurrentMonth(date) {
      return date.getMonth() === this.currentDate.getMonth() &&
             date.getFullYear() === this.currentDate.getFullYear()
    },

    getStatsForDate(date) {
      const dayStart = new Date(date.setHours(0, 0, 0, 0))
      const dayEnd = new Date(date.setHours(23, 59, 59, 999))

      const dayLeads = this.leads.filter(lead => {
        const callDate = new Date(lead.dialedDate  ||  lead.createAt)
        return callDate >= dayStart && callDate <= dayEnd
      })

      return {
        totalCalls: dayLeads.length,
        highRated: dayLeads.filter(lead => lead.rating > 3).length
      }
    },

    getCallVolumeClass(callCount) {
      if (callCount === 0) return ''
      if (callCount <= 3) return 'low-volume'
      if (callCount <= 7) return 'medium-volume'
      return 'high-volume'
    },

    async previousMonth() {
      this.currentDate = new Date(
        this.currentDate.getFullYear(),
        this.currentDate.getMonth() - 1,
        1
      )
      await this.fetchLeads()
    },

    async nextMonth() {
      this.currentDate = new Date(
        this.currentDate.getFullYear(),
        this.currentDate.getMonth() + 1,
      )
      await this.fetchLeads()
    }
  },

  async created() {
    await this.fetchLeads()
  }
}
</script>

<style scoped>
.calendar-container {
  max-width: 1000px;
  margin: 0 auto;
  font-family: Arial, sans-serif;
  padding: 20px;
}

.loading-state,
.error-state {
  text-align: center;
  padding: 40px;
  font-size: 1.2em;
  color: #666;
}

.error-state {
  color: #dc3545;
}

.calendar-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.nav-button {
  padding: 8px 16px;
  font-size: 16px;
  cursor: pointer;
  border: 1px solid #ddd;
  background: #fff;
  border-radius: 4px;
}

.stats-summary {
  display: flex;
  gap: 20px;
  margin-bottom: 20px;
  padding: 15px;
  background: #f8f9fa;
  border-radius: 8px;
}

.stat-item {
  display: flex;
  gap: 8px;
}

.stat-label {
  font-weight: bold;
  color: #666;
}

.stat-value {
  color: #2c3e50;
}

.weekday-header {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  text-align: center;
  font-weight: bold;
  margin-bottom: 10px;
  background: #f8f9fa;
  padding: 10px 0;
}

.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
}

.calendar-day {
  border: 1px solid #ddd;
  padding: 10px;
  min-height: 90px;
  background: #fff;
  opacity: 0.5;
  transition: all 0.2s ease;
}

.calendar-day.current-month {
  opacity: 1;
}

.calendar-day.has-calls {
  background: #f8f9fa;
}

.date {
  font-weight: bold;
  margin-bottom: 8px;
  color: #2c3e50;
}

.stats {
  font-size: 0.9em;
}

.total-calls {
  margin-bottom: 4px;
}

.low-volume {
  color: #3498db;
}

.medium-volume {
  color: #2ecc71;
}

.high-volume {
  color: #e74c3c;
}

.high-rated {
  color: #27ae60;
}
</style>