<template>
  <tr>
    <td style="border: 1px solid #ccc; padding: 8px;">
      <input v-model="item.description" type="text" style="width: 100%; border: none;" />
    </td>
    <td style="border: 1px solid #ccc; padding: 8px; text-align: center;">
      <img
        v-if="item.url"
        :src="thumbnailUrl"
        alt="Thumbnail"
        class="thumbnail"
        @click="openEnlargeDialog"
      />
      <span v-else>No Thumbnail</span>
    </td>
    <td style="border: 1px solid #ccc; padding: 8px; text-align: center;">
      <button @click="openUploadDialog" class="upload-btn">Upload</button>
      <button @click="remove" class="remove-btn">X</button>
    </td>

    <!-- Upload Popup Dialog -->
    <v-dialog
      v-model="uploadDialog"
      max-width="600px"
      z-index="2500"
      class="upload-dialog"
    >
      <v-card>
        <v-card-title>Upload Document</v-card-title>
        <v-card-text>
          <cloudinary-uploader @upload-success="handleUploadSuccess" />
        </v-card-text>
        <v-card-actions>
          <v-btn color="primary" text @click="uploadDialog = false">Close</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <!-- Enlarge Image/PDF Dialog -->
    <v-dialog
      v-model="enlargeDialog"
      max-width="800px"
      z-index="2500"
      class="enlarge-dialog"
    >
      <v-card>
        <v-card-title>Document Preview</v-card-title>
        <v-card-text>
          <img v-if="isImage" :src="item.url" alt="Enlarged Image" class="enlarged-image" />
          <iframe v-else-if="item.url" :src="item.url" width="100%" height="500px"></iframe>
        </v-card-text>
        <v-card-actions>
          <v-btn color="primary" text @click="enlargeDialog = false">Close</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>
  </tr>
</template>

<script>
import { ref, computed, defineAsyncComponent } from 'vue'

export default {
  name: 'DocumentItem',
  components: {
    CloudinaryUploader: defineAsyncComponent(() => import('./CloudinaryUploader.vue')), // Dynamic import
  },
  props: {
    item: Object,
    index: Number,
  },
  emits: ['remove', 'update-url'],
  setup(props, { emit }) {
    const uploadDialog = ref(false)
    const enlargeDialog = ref(false)

    const openUploadDialog = () => {
      uploadDialog.value = true
    }

    const handleUploadSuccess = (uploadResult) => {
      emit('update-url', props.index, uploadResult.secure_url)
      uploadDialog.value = false
    }

    const remove = () => {
      emit('remove', props.index, props.item.url) // Pass the URL along with the index
    }

    const openEnlargeDialog = () => {
      enlargeDialog.value = true
    }

    const isImage = computed(() => {
      if (!props.item.url) return false
      const extension = props.item.url.split('.').pop().toLowerCase()
      return ['jpg', 'jpeg', 'png', 'gif'].includes(extension)
    })

    const thumbnailUrl = computed(() => {
      if (!props.item.url) return ''
      if (isImage.value) return props.item.url
      const publicId = props.item.url.split('/').pop().split('.')[0]
      return `https://res.cloudinary.com/alvin-tan/image/upload/w_100,h_100,c_fill/${publicId}.jpg`
    })

    return {
      uploadDialog,
      enlargeDialog,
      openUploadDialog,
      handleUploadSuccess,
      remove,
      openEnlargeDialog,
      isImage,
      thumbnailUrl,
    }
  },
}
</script>

<style scoped>
.upload-btn {
  padding: 4px 8px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  margin-right: 5px;
}

.upload-btn:hover {
  background-color: #0056b3;
}

.remove-btn {
  padding: 4px 8px;
  background-color: #dc3545;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.remove-btn:hover {
  background-color: #c82333;
}

.upload-dialog,
.enlarge-dialog {
  z-index: 2500 !important;
}

:deep(.upload-dialog .v-overlay__content),
:deep(.enlarge-dialog .v-overlay__content) {
  max-height: 80vh;
  width: 600px;
}

.thumbnail {
  max-width: 50px;
  height: auto;
  cursor: pointer;
}

.enlarged-image {
  max-width: 100%;
  height: auto;
}
</style>