import { createRouter, createWebHistory } from 'vue-router';
import counterDisp from '../components/counter-display.vue';
import kanban from '../components/kanban-board.vue';
import listCards from '../components/list-cards.vue';
import listPhones from '../components/list-phones.vue';
import scheduler from '../components/scheduler-view.vue';
import performance from '../components/performance-metrics.vue';
import listView from '../components/list-view.vue';
import recordView from '../components/record-view.vue';
import testcom from '../components/test-component.vue';
import salesFunnel from '../components/sales-funnel.vue';
import messageCRUD from '../components/message-crud.vue';
import todoList from '../components/todo-list.vue';
import ckEditor from '../components/ck-editor.vue';
import NoteEditorDialog from '../components/NoteEditorDialog.vue'; // Adjust path as needed
import contactsManager from '../components/contacts-manager.vue'; // Adjust path as needed
import firebaseMessaging from '../components/firebaseMessaging.vue'; // Adjust path as needed
const routes = [
  { path: '/', name: 'home', component: todoList },
  { path: '/todoList', name: 'todoList', component: todoList },
  { path: '/kanban', name: 'kanban', component: kanban },
  { path: '/counterDisplay', name: 'counterDisplay', component: counterDisp },
  { path: '/listCards', name: 'listCards', component: listCards },
  { path: '/listPhones', name: 'listPhones', component: listPhones },
  { path: '/scheduler', name: 'scheduler', component: scheduler },
  { path: '/salesFunnel', name: 'salesFunnel', component: salesFunnel },
  { path: '/listView', name: 'listView', component: listView },
  { path: '/recordView/:id', name: 'recordView', component: recordView, props: true },
  { path: '/testcom', name: 'testcom', component: testcom },
  { path: '/performance', name: 'performance', component: performance },
  { path: '/messageCrud', name: 'messageCrud', component: messageCRUD },
  { path: '/ckEditor', name: 'ckEditor', component: ckEditor },
  { path: '/contactsManager', name: 'contactsManager', component: contactsManager },
  { path: '/firebaseMessaging', name: 'firebaseMessaging', component: firebaseMessaging },
  // {
  //   path: '/note-editor/:note?', // Optional :id for editing specific notes
  //   name: 'NoteEditor',
  //   component: NoteEditorDialog,
  //   props: (route) => ({
  //     open: true, // Always open when routed to
  //     isEditing: !!route.params.id, // True if there's an ID
  //     note: route.params.id ? { id: route.params.id } : null, // Pass note data if editing
  //   }),
  // },

  {
    path: '/note-editor/:id?',
    name: 'NoteEditor',
    component: NoteEditorDialog,
    props: (route) => ({
        open: true,
        isEditing: true,
        note: route.params.note ? JSON.parse(route.params.note) : null,
    }),
},

];

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL || '/'), // Ensure BASE_URL is set or default to '/'
  routes,
});

export default router;