<template>

    <EditContactForm :index="selectedIndex" :contacts="contacts" :on-save="saveContact" :nextContact="nextValidContact"
      :on-cancel="cancelEdit" :selectedUser="selectedUser" :selectedPhoneId="selectedPhoneId" v-show="currentContact"
      :contact="currentContact" :on-delete="confirmDelete" />
  
    <div class="filter-label">Filter by Contact Type:</div>
  
    <div v-if="currentContact == null" class="contact-list">
      <p>Project Filter: {{ projectFilter }}</p>
      <p>Rating Filter >=: {{ ratingFilter }}</p>
      <h2>Contact List</h2>
  
      <div class="filter-buttons d-flex flex-nowrap align-center">
        <v-btn width="150" @click="loadData()" color="primary" class="filter-btn">Load Data</v-btn>
        <v-btn width="150" @click="showAddDialog" color="secondary" class="filter-btn">Add Rent Rec</v-btn>
        <v-btn width="150" @click="printToPDF" color="success" class="filter-btn">
          Print to PDF
        </v-btn>
        <v-btn width="150" @click="toggleLeaseFromFilter"
          :class="['filter-btn', { 'active': showContactFromOnly, 'lease-from-active': showContactFromOnly }]" 
          color="accent">
          Lease From {{ showContactFromOnly ? 'Only' : 'All' }}
        </v-btn>
      </div>

        <div>
        <RequestTypeUpdate :contacts="contacts" :disabled="true" :key="componentKey" />
        <component :is="RequestTypeUpdate" :key="componentKey" :contacts="contacts" :disabled="true" />
  
 
  
       
        <v-text-field v-model="interactionFilterValue" placeholder="Enter interaction text" outlined dense
          class="mt-4 ml-4" style="max-width: 300px;"></v-text-field>
   
      </div>
         <!-- Horizontal filter buttons row -->
         <div class="d-flex flex-nowrap overflow-x-auto" style="max-width: 1600px;">
          <v-btn width="150px"
            v-for="(value, type) in activeFilters" 
            :key="type" 
            @click="toggleContactType(type)"
            :class="getButtonClass(type)" 
            class="mx-1"
          >
            {{ type }}
          </v-btn>
        </div>
      <div v-if="dataLoaded" class="record-count">
        Total Records Retrieved: {{ contacts.length }}
      </div>
      <p v-if="!loading && sortedContacts.length > 0">Records Listed: {{ sortedContacts.length }}</p>
      <p v-if="loading">Loading...</p>
      <p v-if="!loading && sortedContacts.length === 0">No contacts found.</p>
  
      <v-data-table v-if="!loading && sortedContacts.length > 0" :headers="headers" :items="sortedContacts"
        :items-per-page="-1" :sort-by="sortBy" :sort-desc="sortDesc" multi-sort class="elevation-5 mt-4 styled-table"
        :footer-props="{
          'items-per-page-options': [10, 25, 50, 100],
          'items-per-page-text': 'Rows per page:',
        }" @update:sort-by="updateSort" ref="dataTable">
        <template v-slot:item="{ item, index }">
          <tr>
            <td class="no-padding" width="30">
              <v-btn width="5" text @click="dialPhone(item, index)">
                {{ item.no }}
              </v-btn>
            </td>
            <td>{{ item.id }}</td>
            <td>{{ item.project }}</td>
            <td>{{ item.requestType }}</td>
            <td>{{ item.rating }}</td>
            <td>{{ item.status }}</td>
            <td>{{ item.name }}</td>
            <td>{{ item.phoneNumber }}</td>
            <td>{{ item.dialedDate }}</td>
            <td>{{ item.location }}</td>
            <td>{{ item.address }}</td>
            <td>{{ item.leaseFrom }}</td>
            <td>{{ item.leaseTo }}</td>
            <td>{{ calculateMonthsPassed(item.leaseFrom).toFixed(1) }} months</td>
            <td>{{ item.interaction }}</td>
            <td>
              <v-btn @click="recordView(item.id)" color="primary" small class="mr-2 action-button">View</v-btn>
              <v-btn @click="editView(item)" color="secondary" small class="action-button">Edit</v-btn>
            </td>
          </tr>
        </template>
      </v-data-table>
  
      <CardDetailsDialog v-if="isSaveDialogVisible" :isSaveDialogVisible="isSaveDialogVisible"
        :selectedCard="selectedCard" :taskMode="taskMode" @close-dialog="closeDialog" @save-changes="handleSaveChanges" />
      <AddTaskDialog :visible="isAddDialogVisible" :requestType="'rent'" @close="closeAddDialog" @save="saveDialog" />
      <ProjectSelectionDialog :visible="showProjectDialog" @close="showProjectDialog = false"
        @select-data="handleProjectSelect" />
    </div>
  </template>


  <script setup>
  import { ref, computed, onMounted, onUnmounted } from 'vue'
  import { useRouter } from 'vue-router'
  import { handleAddRecord, loadByProject } from '../utils/vgraphql.js'
  import { updateContact2 } from '../utils/contactUtils.js'
  import CardDetailsDialog from './cardDetailsDialog.vue'
  import AddTaskDialog from './AddTaskDialog.vue'
  import ProjectSelectionDialog from './projectSelectionDialog.vue'
  import RequestTypeUpdate from './RequestTypeUpdate.vue'
  import html2canvas from 'html2canvas'
  import jsPDF from 'jspdf'
  import EditContactForm from "@/components/EditContactForm.vue"
  import { useUserStore } from '@/stores/user'
  import { isPhoneDisabled } from '../utils/contactUtils.js'
  
  // IndexedDB Constants
  const DB_NAME = 'ContactDB'
  const DB_VERSION = 1
  const STORE_NAME = 'contacts'
  
  // Reactive State
  const router = useRouter()
  const userStore = useUserStore()
  const db = ref(null)
  const contacts = ref([])
  const loading = ref(false)
  const dataLoaded = ref(false)
  const currentContact = ref(null)
  const selectedIndex = ref(-1)
  const componentKey = ref(0)
  const sortBy = ref(['rating'])
  const sortDesc = ref([true])
  const selectedContactType = ref('all')
  const interactionFilterValue = ref('')
  const isSaveDialogVisible = ref(false)
  const taskMode = ref('all')
  const selectedCard = ref(null)
  const projectFilter = ref('all')
  const locationFilter = ref('all')
  const dialedDateFilter = ref('null')
  const ratingFilter = ref(4)
  const isAddDialogVisible = ref(false)
  const showContactFromOnly = ref(false)
  const showProjectDialog = ref(false)
  const tempContacts = ref([])
  
  const activeFilters = ref({
    all: false,
    rent: false,
    seller: false,
    owner: false,
    lease: false,
    tenanted: false,
    Lease_Expiry: false,
    buyer: false,
    project_buyer: false,
    project_seller: false,
  })
  
  // Table Headers
  const headers = [
    { text: 'ID', title: 'ID', value: 'id', sortable: true },
    { text: 'No', title: 'No', value: 'no', sortable: true },
    { text: 'Project', title: 'Project', value: 'project', sortable: true },
    { text: 'Request Type', title: 'Request Type', value: 'requestType', sortable: true },
    { text: 'Rating', title: 'Rating', value: 'rating', sortable: true },
    { text: 'Status', title: 'Status', value: 'status', sortable: true },
    { text: 'Name', title: 'Name', value: 'name', sortable: true },
    { text: 'Phone Number', title: 'Phone Number', value: 'phoneNumber', sortable: true },
    { text: 'Dialed Date', title: 'Dialed Date', value: 'dialedDate', sortable: true },
    { text: 'Location', title: 'Location', value: 'location', sortable: true },
    { text: 'Address', title: 'Address', value: 'address', sortable: true },
    { text: 'Lease From', title: 'Lease From', value: 'contactFrom', align: 'center', sortable: true },
    { text: 'Lease To', title: 'Lease To', value: 'contactTo', align: 'center', sortable: true },
    { text: 'Months Passed', title: 'Months Passed', value: 'monthsPassed', align: 'center', sortable: true },
    { text: 'Interaction', title: 'Integration', value: 'interaction', sortable: true },
    { text: 'Actions', title: 'Action', value: 'actions', sortable: false },
  ]
  
  // Helper Functions
  const parseDate = (dateStr) => {
    if (!dateStr) return null
    const parts = dateStr.split('/')
    if (parts.length === 3) {
      const [day, month, year] = parts.map(Number)
      return new Date(year, month - 1, day).toISOString()
    }
    try {
      const date = new Date(dateStr)
      return isNaN(date.getTime()) ? null : date.toISOString()
    } catch {
      return null
    }
  }
  
  const cleanContactData = (contact) => ({
    id: String(contact.id || ''),
    location: String(contact.location || ''),
    no: Number(contact.no) || 0,
    name: String(contact.name || ''),
    phoneNumber: String(contact.phoneNumber || ''),
    project: String(contact.project || ''),
    status: String(contact.status || ''),
    interaction: String(contact.interaction || ''),
    rating: Number(contact.rating) || 0,
    dialedDate: parseDate(contact.dialedDate),
    requestType: String(contact.requestType || ''),
    leaseFrom: parseDate(contact.leaseFrom),
    leaseTo: parseDate(contact.leaseTo),
    // ... (other fields from original cleanContactData)
  })
  
  // IndexedDB Functions
  const initDB = () => new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION)
    request.onerror = () => reject(request.error)
    request.onsuccess = () => resolve(request.result)
    request.onupgradeneeded = (event) => {
      event.target.result.createObjectStore(STORE_NAME, { keyPath: 'id' })
    }
  })
  
  const saveToDB = async (db, contacts) => {
    const transaction = db.transaction([STORE_NAME], 'readwrite')
    const store = transaction.objectStore(STORE_NAME)
    contacts.forEach(contact => store.put(cleanContactData(contact)))
    return new Promise((resolve, reject) => {
      transaction.oncomplete = resolve
      transaction.onerror = () => reject(transaction.error)
    })
  }
  
  const loadFromDB = async (db) => {
    const transaction = db.transaction([STORE_NAME], 'readonly')
    const store = transaction.objectStore(STORE_NAME)
    return new Promise((resolve, reject) => {
      const request = store.getAll()
      request.onsuccess = () => resolve(request.result)
      request.onerror = () => reject(request.error)
    })
  }
  
  const clearDB = async (db) => {
    const transaction = db.transaction([STORE_NAME], 'readwrite')
    const store = transaction.objectStore(STORE_NAME)
    return new Promise((resolve, reject) => {
      const request = store.clear()
      request.onsuccess = resolve
      request.onerror = () => reject(request.error)
    })
  }
  
  // Component Logic
  const dialPhone = (item, index) => {
    selectedIndex.value = index
    currentContact.value = { ...item }
  }
  
  const saveContact = async (updatedData) => {
    try {
      loading.value = true
      const updatedContact = await updateContact2(currentContact.value.id, updatedData)
      const index = contacts.value.findIndex(c => c.id === updatedContact.id)
      if (index !== -1) contacts.value[index] = updatedContact
      await saveToDB(db.value, contacts.value)
      currentContact.value = null
    } catch (error) {
      console.error('Save failed:', error)
      alert(`Save failed: ${error.message}`)
    } finally {
      loading.value = false
    }
  }
  
  const nextValidContact = () => {
    selectedIndex.value = selectedIndex.value < contacts.value.length - 1 
      ? selectedIndex.value + 1 
      : 0
    currentContact.value = contacts.value[selectedIndex.value]
    if (isPhoneDisabled(currentContact.value)) nextValidContact()
  }
  
  const handleProjectSelect = async (data) => {
    try {
      componentKey.value++
      loading.value = true
      await clearDB(db.value)
      contacts.value = []
      await loadByProject(
        data.project,
        data.location,
        data.dialedDate,
        data.rating,
        contacts
      )
      await saveToDB(db.value, contacts.value)
      dataLoaded.value = true
      showProjectDialog.value = false
    } catch (error) {
      console.error('Load failed:', error)
      alert('Failed to load data')
    } finally {
      loading.value = false
    }
  }
  
  // Computed Properties
  const sortedContacts = computed(() => {
    return contacts.value
      .filter(contact => {
        const typeMatch = selectedContactType.value === 'all' || 
          contact.requestType === selectedContactType.value
        const interactionMatch = !interactionFilterValue.value ||
          contact.interaction?.includes(interactionFilterValue.value)
        const leaseMatch = !showContactFromOnly.value || contact.leaseFrom
        return typeMatch && interactionMatch && leaseMatch
      })
      .map(contact => ({
        ...contact,
        monthsPassed: calculateMonthsPassed(contact.leaseFrom)
      }))
  })
  
  // Lifecycle Hooks
  onMounted(async () => {
    try {
      db.value = await initDB()
      const storedContacts = await loadFromDB(db.value)
      if (storedContacts?.length) {
        contacts.value = [...storedContacts]
        dataLoaded.value = true
      }
    } catch (error) {
      console.error('Initialization failed:', error)
    }
  })
  
  onUnmounted(() => {
    if (db.value) db.value.close()
  })
  
  // Template Methods (keep the rest of your methods here)
  // ... (other methods from original component)

//***********************

 
     const cancelEdit = () => {
      currentContact.value = null;
    };

    const updateSort = (value) => {
      sortBy.value = value;
    };

    const showAddDialog = () => {
      isAddDialogVisible.value = true;
    };

    const handleSaveChanges = async (updatedData) => {
      const index = contacts.value.findIndex(card => card.id === updatedData.id);
      if (index !== -1) {
        contacts.value[index] = updatedData;
        try {
          await saveToDB(db.value, contacts.value);
          console.log('Contacts saved after update');
        } catch (error) {
          console.error('Error saving to IndexedDB:', error);
        }
      }
    };

  

    // async function updateContact(id, data) {
    //   // Assuming this uses fetch or axios to update Strapi
    //   const response = await fetch(`https://sp412b-763ef468411d.herokuapp.com/api/contacts/${id}`, {
    //     method: 'PUT',
    //     headers: { 'Content-Type': 'application/json' },
    //     body: JSON.stringify({ data }) // Strapi expects { data: {...} }
    //   });
    //   if (!response.ok) throw new Error('Failed to update contact in Strapi');
    //   const updatedContact = await response.json();
    //   return updatedContact.data; // Adjust based on Strapi response structure
    // }

    // In listView.vue
    
 

    const toggleContactType = async (type) => {
      if (selectedContactType.value === type) {
        selectedContactType.value = 'all';
        for (let key in activeFilters.value) {
          activeFilters.value[key] = false;
        }
      } else {
        selectedContactType.value = type;
        for (let key in activeFilters.value) {
          activeFilters.value[key] = key === type;
        }
      }
      showContactFromOnly.value = false;
      await fetchContactsByType(selectedContactType.value);
    };

    const toggleLeaseFromFilter = async () => {
      showContactFromOnly.value = !showContactFromOnly.value;
      if (showContactFromOnly.value) {
        for (let key in activeFilters.value) {
          activeFilters.value[key] = false;
        }
        selectedContactType.value = 'all';
      }
    };

    const fetchContactsByType = async (type) => {
      try {
        loading.value = true;
        const filter = type !== 'all' ? { requestType: { eq: type } } : {};
        if (showContactFromOnly.value) {
          filter.leaseFrom = { ne: null };
        }
        await new Promise(resolve => setTimeout(resolve, 1000));
      } catch (error) {
        console.error('Error fetching contacts:', error);
        alert('Failed to fetch contacts. Please try again.');
      } finally {
        loading.value = false;
      }
    };

    const recordView = (contactId) => {
      router.push({ name: 'recordView', params: { id: contactId } });
    };

    const editView = (contact) => {
      if (!contact || !contact.id) {
        console.error('Invalid contact object:', contact);
        alert('Error: Contact data is missing or incomplete.');
        return;
      }
      selectedCard.value = { ...contact };
      taskMode.value = contact.requestType;
      isSaveDialogVisible.value = true;
    };

    const calculateMonthsPassed = (leaseFrom) => {
      if (!leaseFrom) return 0;
      const today = new Date();
      const startDate = new Date(leaseFrom);
      let monthsPassed =
        (today.getFullYear() - startDate.getFullYear()) * 12 + (today.getMonth() - startDate.getMonth());
      if (today.getDate() < startDate.getDate()) monthsPassed--;
      return parseFloat(monthsPassed.toFixed(1));
    };

   
    const closeAddDialog = () => {
      isAddDialogVisible.value = false;
    };

    const saveDialog = async (data) => {
      isAddDialogVisible.value = false;
      handleAddRecord(data, contacts);
      try {
        await saveToDB(db.value, contacts.value);
        console.log('New contact saved via dialog');
      } catch (error) {
        console.error('Error saving to IndexedDB:', error);
      }
    };

    const closeDialog = async () => {
      isSaveDialogVisible.value = false;
    };

    const loadData = async () => {
      showProjectDialog.value = true;
    };


    const getButtonClass = (type) => {
      return {
        'Lease_Expiry': selectedContactType.value === 'Lease_Expiry' && type === 'Lease_Expiry',
        'tenanted-active': selectedContactType.value === 'tenanted' && type === 'tenanted',
        'owner-active': selectedContactType.value === 'owner' && type === 'owner',
        'all-active': selectedContactType.value === 'all' && type === 'all',
        'rent-active': selectedContactType.value === 'rent' && type === 'rent',
        'seller-active': selectedContactType.value === 'seller' && type === 'seller',
        'lease-active': selectedContactType.value === 'lease' && type === 'lease',
        'buyer-active': selectedContactType.value === 'buyer' && type === 'buyer',
        'project-buyer-active': selectedContactType.value === 'project_buyer' && type === 'project_buyer',
        'project-seller-active': selectedContactType.value === 'project_seller' && type === 'project_seller',
      };
    };

    const printToPDF = () => {
      const actionButtons = document.querySelectorAll('.action-button');
      actionButtons.forEach(button => button.style.display = 'none');

      const table = document.querySelector('.v-data-table');
      if (table) {
        html2canvas(table).then((canvas) => {
          const imgData = canvas.toDataURL('image/png');
          const pdf = new jsPDF('p', 'mm', 'a4');
          const imgWidth = 210;
          const imgHeight = (canvas.height * imgWidth) / canvas.width;
          pdf.addImage(imgData, 'PNG', 0, 0, imgWidth, imgHeight);
          pdf.save('contact-list.pdf');
          actionButtons.forEach(button => button.style.display = '');
        });
      }
    };

    onUnmounted(() => {
      if (db.value) {
        db.value.close();
        console.log('Database closed');
      }
      console.log('ContactList component unmounted');
      componentKey.value = 0;
    });

</script>

<style src="@/assets/css/contact-list.css"></style>
