<template>
  <div>
    <v-card>
      <v-card-title>
        Message Templates
        <v-spacer></v-spacer>
        <v-btn color="primary" @click="openNewDialog">
          <v-icon left>mdi-plus</v-icon>
          New Template
        </v-btn>
      </v-card-title>

      <v-data-table :headers="headers" :items="messages" :loading="loading" :items-per-page="-1" loading-text="Loading messages...">
        <template v-slot:item.message="{ item }">
          <pre style="white-space: pre-wrap">{{ item.attributes.message }}</pre>
        </template>
        <template v-slot:item.messageC="{ item }">
          <pre style="white-space: pre-wrap">{{ item.attributes.messageC }}</pre>
        </template>
        <template v-slot:item.messageM="{ item }">
          <pre style="white-space: pre-wrap">{{ item.attributes.messageM }}</pre>
        </template>
        <template v-slot:item.requestType="{ item }">
          {{ item.attributes.requestType }}
        </template>

        <template v-slot:item.actions="{ item }">
          <v-icon small class="mr-2" @click="editItem(item)">
            mdi-pencil
          </v-icon>
          <v-icon small @click="deleteItem(item)">
            mdi-delete
          </v-icon>
        </template>
      </v-data-table>
    </v-card>

    <v-dialog v-model="dialog" max-width="600px">
      <v-card>
        <v-card-title>
          <span class="headline">{{ formTitle }}</span>
        </v-card-title>

        <v-card-text>
          <v-container>
            <v-form ref="form">
              <v-text-field v-model="editedItem.attributes.title" label="Title" required></v-text-field>

              <v-textarea v-model="editedItem.attributes.message" label="Message (English)" required rows="4"
                auto-grow></v-textarea>

              <v-textarea v-model="editedItem.attributes.messageC" label="Message (Chinese)" rows="4"
                auto-grow></v-textarea>

              <v-textarea v-model="editedItem.attributes.messageM" label="Message (Malay)" rows="4"
                auto-grow></v-textarea>

              <v-select v-model="editedItem.attributes.category" :items="categories" label="Category"
                required></v-select>

              <v-select v-model="editedItem.attributes.requestType" :items="requestTypes" label="Request Type"
                required></v-select>
            </v-form>
          </v-container>
        </v-card-text>

        <v-card-actions>
          <v-spacer></v-spacer>
          <v-btn color="blue darken-1" text @click="closeDialog">
            Cancel
          </v-btn>
          <v-btn color="blue darken-1" text @click="saveMessage">
            Save
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <v-dialog v-model="dialogDelete" max-width="500px">
      <v-card>
        <v-card-title class="headline">Are you sure you want to delete this template?</v-card-title>
        <v-card-actions>
          <v-spacer></v-spacer>
          <v-btn color="blue darken-1" text @click="closeDelete">Cancel</v-btn>
          <v-btn color="blue darken-1" text @click="deleteConfirm">OK</v-btn>
          <v-spacer></v-spacer>
        </v-card-actions>
      </v-card>
    </v-dialog>
  </div>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue';
import { useQuery, useMutation } from '@vue/apollo-composable';
import { gql } from '@apollo/client/core';

const MESSAGES_QUERY = gql`
 query GetMessage {
  messages(pagination: { limit: 1000 }, sort: ["title"]) {

      data {
        id
        attributes {
          title
          message
          messageC
          messageM
          category
          requestType
          createdAt
          updatedAt
        }
      }
    }
  }
`;

const CREATE_MESSAGE = gql`
  mutation CreateMessage($input: MessageInput!) {
    createMessage(data: $input) {
      data {
        id
        attributes {
          title
          message
          messageC
          messageM
          category
          requestType
        }
      }
    }
  }
`;

const UPDATE_MESSAGE = gql`
  mutation UpdateMessage($id: ID!, $input: MessageInput!) {
    updateMessage(id: $id, data: $input) {
      data {
        id
        attributes {
          title
          message
          messageC
          messageM
          category
          requestType
        }
      }
    }
  }
`;

const DELETE_MESSAGE = gql`
  mutation DeleteMessage($id: ID!) {
    deleteMessage(id: $id) {
      data {
        id
      }
    }
  }
`;

const headers = [
  { text: 'Title', value: 'attributes.title' },
  { text: 'Message (EN)', value: 'message' },
  { text: 'Message (CN)', value: 'messageC' },
  { text: 'Message (MY)', value: 'messageM' },
  { text: 'Category', value: 'attributes.category' },
  { text: 'Request Type', value: 'requestType' },
  { text: 'Actions', value: 'actions', sortable: false },
];

const categories = ['Sales', 'Rental', 'Follow-up', 'General'];
const requestTypes = [
  'owner',
  'tenanted',
  'buyer',
  'project_buyer',
  'seller',
  'rent',
  'lease',
  'sell or lease',
  'task',
  'undefined'
];

const messages = ref([]);
const loading = ref(false);
const dialog = ref(false);
const dialogDelete = ref(false);
const editedItem = ref({
  id: null,
  attributes: {
    title: '',
    message: '',
    messageC: '',
    messageM: '',
    category: '',
    requestType: 'undefined'
  }
});
const defaultItem = ref({
  id: null,
  attributes: {
    title: '',
    message: '',
    messageC: '',
    messageM: '',
    category: '',
    requestType: 'undefined'
  }
});

const formTitle = computed(() => editedItem.value.id ? 'Edit Template' : 'New Template');

const { refetch: fetchMessages } = useQuery(MESSAGES_QUERY, null, {
  fetchPolicy: 'network-only',
});

const { mutate: createMessage } = useMutation(CREATE_MESSAGE);
const { mutate: updateMessage } = useMutation(UPDATE_MESSAGE);
const { mutate: deleteMessage } = useMutation(DELETE_MESSAGE);

onMounted(async () => {
  await loadMessages();
});

async function loadMessages() {
  try {
    loading.value = true;
    const { data } = await fetchMessages();
    messages.value = data.messages.data;
  } catch (error) {
    console.error('Error loading messages:', error);
  } finally {
    loading.value = false;
  }
}

function openNewDialog() {
  editedItem.value = { ...defaultItem.value };
  dialog.value = true;
}

function editItem(item) {
  editedItem.value = {
    id: item.id,
    attributes: { ...item.attributes }
  };
  dialog.value = true;
}

async function saveMessage() {
  try {
    const input = {
      title: editedItem.value.attributes.title,
      message: editedItem.value.attributes.message,
      messageC: editedItem.value.attributes.messageC,
      messageM: editedItem.value.attributes.messageM,
      category: editedItem.value.attributes.category,
      requestType: editedItem.value.attributes.requestType
    };

    if (editedItem.value.id) {
      await updateMessage({
        id: editedItem.value.id,
        input
      });
    } else {
      await createMessage({ input });
    }

    await loadMessages();
    closeDialog();
  } catch (error) {
    console.error('Error saving message:', error);
  }
}

function deleteItem(item) {
  editedItem.value = { ...item };
  dialogDelete.value = true;
}

async function deleteConfirm() {
  try {
    await deleteMessage({ id: editedItem.value.id });
    await loadMessages();
    closeDelete();
  } catch (error) {
    console.error('Error deleting message:', error);
  }
}

function closeDialog() {
  dialog.value = false;
  editedItem.value = { ...defaultItem.value };
}

function closeDelete() {
  dialogDelete.value = false;
  editedItem.value = { ...defaultItem.value };
}
</script>

<style scoped>
pre {
  font-family: inherit;
  margin: 0;
  white-space: pre-wrap;
  word-wrap: break-word;
}
</style>