// src/firebase.js
import { initializeApp } from 'firebase/app';
import { 
  getMessaging, 
  onMessage,
  getToken,
  deleteToken,
  isSupported
} from 'firebase/messaging';

const firebaseConfig = {
  apiKey: "AIzaSyCAwYbe9Co9y1g_3oG3bcjHX5VSaN44B8U",
  authDomain: "image-api-f55eb.firebaseapp.com",
  projectId: "image-api-f55eb",
  storageBucket: "image-api-f55eb.firebasestorage.app",
  messagingSenderId: "981505208035",
  appId: "1:981505208035:web:e5b695b767a2d6d8529fd6",
  measurementId: "G-KKVCQV1YX0"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);

// Function to initialize messaging
const initializeMessaging = async () => {
  if (typeof window === 'undefined') {
    console.warn('Firebase Messaging not available: Not in browser environment');
    return null;
  }

  try {
    const supported = await isSupported();
    if (!supported) {
      console.warn('Firebase Messaging is not supported in this environment');
      return null;
    }
    return getMessaging(app);
  } catch (error) {
    console.error('Error initializing Firebase Messaging:', error);
    return null;
  }
};

// Export messaging as a promise
export const messagingPromise = initializeMessaging();

// Export other functions
export { getToken, deleteToken, onMessage };

// Updated requestPermission function
export const requestPermission = async () => {
  try {
    const messaging = await messagingPromise;
    if (!messaging) {
      throw new Error('Messaging not available or not supported');
    }

    const permission = await Notification.requestPermission();
    if (permission !== 'granted') {
      console.log('Notification permission denied');
      return null;
    }

    const token = await getToken(messaging, {
      vapidKey: 'BHdcF8FqBi23zOaWoWO34P_C4hHwwG1XfsBSB-k-DhNBRn32iLh2214kzKNOhdJQ-plMtOHQojlkykCv8L9CBBA'
    });
    return token;
  } catch (error) {
    console.error('Error getting token:', error);
    return null;
  }
};